package br.pucminas.puclim.controller;
import br.pucminas.puclim.exception.ApiException; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@RestController @RequestMapping("/api/uploads/imagens") public class ImageController {
 private final Path root=Paths.get("storage/images");
 @PostMapping public Map<String,String> upload(@RequestParam MultipartFile file) throws IOException {if(file.isEmpty()||file.getSize()>2*1024*1024)throw new ApiException("Envie uma imagem JPG ou PNG de até 2 MB.");String type=Optional.ofNullable(file.getContentType()).orElse("");if(!type.equals("image/jpeg")&&!type.equals("image/png"))throw new ApiException("Envie uma imagem JPG ou PNG válida.");byte[] bytes=file.getBytes();boolean jpg=bytes.length>3&&(bytes[0]&255)==255&&(bytes[1]&255)==216&&(bytes[2]&255)==255;boolean png=bytes.length>8&&bytes[0]==(byte)137&&bytes[1]==80&&bytes[2]==78&&bytes[3]==71&&bytes[4]==13&&bytes[5]==10&&bytes[6]==26&&bytes[7]==10;if(!jpg&&!png)throw new ApiException("O conteúdo do arquivo não é uma imagem válida.");Files.createDirectories(root);String name=UUID.randomUUID()+(jpg?".jpg":".png");Files.write(root.resolve(name),bytes,StandardOpenOption.CREATE_NEW);return Map.of("url","/api/uploads/imagens/"+name);}
 @GetMapping("/{filename}") public ResponseEntity<byte[]> get(@PathVariable String filename)throws IOException{if(!filename.matches("[a-f0-9-]+\\.(jpg|png)"))throw new ApiException("Imagem não encontrada.",404);Path path=root.resolve(filename).normalize();if(!path.startsWith(root.toAbsolutePath().normalize())||!Files.exists(path))throw new ApiException("Imagem não encontrada.",404);String type=filename.endsWith(".jpg")?"image/jpeg":"image/png";return ResponseEntity.ok().header("X-Content-Type-Options","nosniff").contentType(MediaType.parseMediaType(type)).body(Files.readAllBytes(path));}
}